import api.SettlementApi;
import domain.DailyLine;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;

/** Per-transaction partner statement (sample data in fixtures/). */
public class PartnerDetailE2ETest {
    private static final LocalDate FROM = LocalDate.of(2026, 10, 1);
    private static final LocalDate TO = LocalDate.of(2026, 10, 5);

    public static void main(String[] args) {
        TestSupport t = new TestSupport("detail");
        SettlementApi api = SettlementApi.fromDefaultConfig();
        String p1 = api.partnerDetailText("P-1001", FROM, TO);

        t.test("first line names the partner and the period", () -> {
            String first = p1.lines().findFirst().orElse("");
            TestSupport.check(first.contains("P-1001") && first.contains("트래블메이트"), "header: " + first);
        });

        t.test("one line per transaction of the partner, nothing else", () -> {
            for (String id : List.of("T0001", "T0004", "T0007", "T0008", "T0011", "T0012", "T0016", "T0018")) {
                TestSupport.check(line(p1, id) != null, "missing " + id + "\n" + p1);
            }
            for (String id : List.of("T0002", "T0013", "T0021")) {
                TestSupport.check(line(p1, id) == null, "should not list " + id + "\n" + p1);
            }
        });

        t.test("weekday lines show the rate and the KRW amount", () -> {
            TestSupport.check(line(p1, "T0001").contains("1,377.30"), line(p1, "T0001"));
            TestSupport.check(line(p1, "T0001").contains("165,965"), line(p1, "T0001"));
            TestSupport.check(line(p1, "T0007").contains("1,386.02"), line(p1, "T0007"));
            TestSupport.check(line(p1, "T0007").contains("45,877"), line(p1, "T0007"));
            String p3 = api.partnerDetailText("P-1003", FROM, TO);
            TestSupport.check(line(p3, "T0003").contains("925.86") && line(p3, "T0003").contains("146,286"), line(p3, "T0003"));
        });

        t.test("KRW per line is the settled amount", () -> {
            TestSupport.check(line(p1, "T0011").contains("82,746"), line(p1, "T0011"));
            TestSupport.check(line(p1, "T0016").contains("125,254"), line(p1, "T0016"));
        });

        t.test("total line matches the daily settlement gross", () -> {
            long gross = api.daily(FROM, TO).stream().filter(l -> l.partnerId().equals("P-1001"))
                    .mapToLong(DailyLine::grossKrw).sum();
            String total = p1.lines().filter(l -> l.startsWith("합계")).findFirst().orElse("");
            TestSupport.check(total.contains("8건"), "count: " + total);
            TestSupport.check(total.contains(util.Money.won(gross)), "total " + util.Money.won(gross) + ": " + total);
        });

        t.finish();
    }

    /** The line that lists the given transaction id, or null. */
    static String line(String text, String txnId) {
        return text.lines().filter(l -> Arrays.asList(l.trim().split("\\s+")).contains(txnId)).findFirst().orElse(null);
    }
}
package service;

import domain.DailyLine;
import domain.Partner;
import domain.Transaction;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Builds per-partner daily settlement lines from the transaction feed. */
public class SettlementService {
    private final DataFiles data;
    private final RateService rates;
    private final BusinessDateResolver dates;

    public SettlementService(DataFiles data, RateService rates, BusinessDateResolver dates) {
        this.data = data;
        this.rates = rates;
        this.dates = dates;
    }

    public List<DailyLine> settle(LocalDate from, LocalDate to) {
        Map<String, long[]> acc = new TreeMap<>(); // key "date|partner" -> {count, grossKrw}
        for (Transaction t : data.transactions()) {
            LocalDate d = dates.dateOf(t.approvedAt());
            if (d.isBefore(from) || d.isAfter(to)) continue;
            Partner p = data.partner(t.partnerId()).orElse(null);
            if (p == null || !p.active()) continue;
            long krw = convert(t, d);
            long[] a = acc.computeIfAbsent(d + "|" + p.id(), k -> new long[2]);
            a[0]++;
            a[1] += krw;
        }
        List<DailyLine> out = new ArrayList<>();
        for (var e : acc.entrySet()) {
            String[] k = e.getKey().split("\\|");
            Partner p = data.partner(k[1]).orElseThrow();
            long gross = e.getValue()[1];
            out.add(new DailyLine(LocalDate.parse(k[0]), p.id(), (int) e.getValue()[0], gross,
                    Money.fee(gross, p.feeBps())));
        }
        return out;
    }

    private long convert(Transaction t, LocalDate businessDate) {
        var rate = rates.settlementRate(t.currency(), businessDate);
        return Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    }
}
package service;

import domain.FxQuote;
import infra.FxqClient;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, FxQuote> settledQuotes = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * A lagged quote (trailing ~N) repeats an earlier day's value and must not be settled with;
     * the vendor's source-3 value for that date is used instead.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.lagged()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        return settledQuotes.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.settlementQuote(pair, date));
        }).rate();
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}
